void read_input(int *len, int numbers[]) {
    scanf("%d", len);
    for (int idx = 0; idx < *len; idx++) {
        scanf("%d", &numbers[idx]);
    }
}

int compute_sum(int len, int numbers[]) {
    int sum = 0;
    for (int idx = len - 1; idx >= 0; idx--) {
        sum += numbers[idx];
    }
    return sum;
}

void print_result(int sum) {
    printf("%d\n", sum);
}

int main() {
    int len;
    int numbers[1000];
    read_input(&len, numbers);
    int sum = compute_sum(len, numbers);
    print_result(sum);
    return 0;
}

